-- Golden questions for the isolated synthetic demo; amounts are EUR minor units.
SET ROLE demo_reader; SELECT json_build_object('sessions',(SELECT count(*) FROM demo.sessions),'events',(SELECT count(*) FROM demo.browser_events),'product_views',(SELECT count(*) FROM demo.browser_events WHERE event_type='behavior.product_viewed'),'searches',(SELECT count(*) FROM demo.browser_events WHERE event_type='behavior.search_query_submitted'),'carts',(SELECT count(DISTINCT cart_id) FROM demo.cart_changes),'orders',(SELECT count(*) FROM demo.orders),'order_lines',(SELECT count(*) FROM demo.order_lines),'line_total_eur_minor',(SELECT coalesce(sum(line_total_minor),0) FROM demo.order_lines WHERE currency='EUR'),'captured_eur_minor',(SELECT coalesce(sum(amount_minor),0) FROM demo.payments WHERE action='CAPTURED' AND currency='EUR'),'refunded_eur_minor',(SELECT coalesce(sum(amount_minor),0) FROM demo.payments WHERE action='REFUNDED' AND currency='EUR'),'deleted_cart_lines',(SELECT count(*) FROM demo.cart_changes WHERE change_type='DELETE'),'on_orders',(SELECT count(*) FROM demo.orders WHERE reference_state='ON'),'category_product_views',(SELECT count(*) FROM demo.browser_events e JOIN demo.category_history h ON h.product_id=e.data->>'product_id' AND h.valid_from<=e.occurred_at AND e.occurred_at<h.valid_to WHERE e.event_type='behavior.product_viewed'),'invalid_order_price',(SELECT count(*) FROM demo.order_lines l LEFT JOIN demo.offer_prices p ON p.variant_key=l.variant_key AND p.price_rule=l.price_rule AND p.currency=l.currency AND p.effective_at<=l.ordered_at AND l.ordered_at<p.valid_to WHERE p.variant_key IS NULL OR p.amount_minor<>l.unit_amount_minor),'can_read',has_table_privilege('demo_reader','demo.browser_events','SELECT'),'can_insert',has_table_privilege('demo_reader','demo.records','INSERT'));
